/bin/bash -c "python - <<'PY'
import cv2,numpy as np,time
x=np.load('source_pixels.npz')['rgb']
def make(dispreset):
 dis=cv2.DISOpticalFlow_create(dispreset); dis.setFinestScale(0)
 def flow(a,b): return dis.calc(cv2.cvtColor(a,cv2.COLOR_RGB2GRAY),cv2.cvtColor(b,cv2.COLOR_RGB2GRAY),None)
 def interp(a,b):
  f=flow(a,b); g=flow(b,a); h,w=f.shape[:2]; yy,xx=np.mgrid[0:h,0:w].astype(np.float32)
  wa=cv2.remap(a,xx-f[...,0]*.5,yy-f[...,1]*.5,cv2.INTER_CUBIC,borderMode=cv2.BORDER_REPLICATE)
  wb=cv2.remap(b,xx-g[...,0]*.5,yy-g[...,1]*.5,cv2.INTER_CUBIC,borderMode=cv2.BORDER_REPLICATE)
  return np.rint((wa+wb)/2).clip(0,255).astype(np.uint8)
 return interp
for preset in [cv2.DISOPTICAL_FLOW_PRESET_ULTRAFAST,cv2.DISOPTICAL_FLOW_PRESET_FAST,cv2.DISOPTICAL_FLOW_PRESET_MEDIUM]:
 t0=time.time(); errs=[]; strip=[]
 interp=make(preset)
 for k in range(0,33,2):
  p=interp(x[k],x[k+2]); errs.append(np.abs(p.astype(float)-x[k+1]).mean()); strip.append(np.abs(p[50:90].astype(float)-x[k+1,50:90]).mean())
 print(preset,'err',np.mean(errs),'strip',np.mean(strip),'time',time.time()-t0)
PY"

